// QueryServer is the server API for Query service.
type QueryServer interface {
	// Params queries the economics module parameters
	Params(context.Context, *QueryParamsRequest) (*QueryParamsResponse, error)
	// VestingSchedule queries a vesting schedule by ID
	VestingSchedule(context.Context, *QueryVestingScheduleRequest) (*QueryVestingScheduleResponse, error)
	// VestingSchedulesByAddress queries all vesting schedules for an address
	VestingSchedulesByAddress(context.Context, *QueryVestingSchedulesByAddressRequest) (*QueryVestingSchedulesByAddressResponse, error)
	// AllVestingSchedules queries all vesting schedules
	AllVestingSchedules(context.Context, *QueryAllVestingSchedulesRequest) (*QueryAllVestingSchedulesResponse, error)
	// Proposal queries a proposal by ID
	Proposal(context.Context, *QueryProposalRequest) (*QueryProposalResponse, error)
	// Proposals queries all proposals
	Proposals(context.Context, *QueryProposalsRequest) (*QueryProposalsResponse, error)
	// Vote queries a vote by proposal ID and voter
	Vote(context.Context, *QueryVoteRequest) (*QueryVoteResponse, error)
	// Votes queries all votes for a proposal
	Votes(context.Context, *QueryVotesRequest) (*QueryVotesResponse, error)
	// Deposit queries a deposit by proposal ID and depositor
	Deposit(context.Context, *QueryDepositRequest) (*QueryDepositResponse, error)
	// Deposits queries all deposits for a proposal
	Deposits(context.Context, *QueryDepositsRequest) (*QueryDepositsResponse, error)
	// TallyResult queries the tally of a proposal
	TallyResult(context.Context, *QueryTallyResultRequest) (*QueryTallyResultResponse, error)
	// VoteLock queries a vote lock by ID
	VoteLock(context.Context, *QueryVoteLockRequest) (*QueryVoteLockResponse, error)
	// VoteLocksByOwner queries all vote locks for an owner
	VoteLocksByOwner(context.Context, *QueryVoteLocksByOwnerRequest) (*QueryVoteLocksByOwnerResponse, error)
	// VotingPower queries the voting power for an address
	VotingPower(context.Context, *QueryVotingPowerRequest) (*QueryVotingPowerResponse, error)
	// VoteDelegations queries all vote delegations for a delegator
	VoteDelegations(context.Context, *QueryVoteDelegationsRequest) (*QueryVoteDelegationsResponse, error)
	// PendingTreasuryTx queries a pending treasury transaction
	PendingTreasuryTx(context.Context, *QueryPendingTreasuryTxRequest) (*QueryPendingTreasuryTxResponse, error)
	// PendingTreasuryTxs queries all pending treasury transactions
	PendingTreasuryTxs(context.Context, *QueryPendingTreasuryTxsRequest) (*QueryPendingTreasuryTxsResponse, error)
	// InflationMetrics queries current inflation metrics
	InflationMetrics(context.Context, *QueryInflationMetricsRequest) (*QueryInflationMetricsResponse, error)
	// MEVStats queries MEV redistribution statistics
	MEVStats(context.Context, *QueryMEVStatsRequest) (*QueryMEVStatsResponse, error)
	// UserMEVBalance queries a user's MEV redistribution balance
	UserMEVBalance(context.Context, *QueryUserMEVBalanceRequest) (*QueryUserMEVBalanceResponse, error)
	// LiquidityMiningStats queries liquidity mining statistics
	LiquidityMiningStats(context.Context, *QueryLiquidityMiningStatsRequest) (*QueryLiquidityMiningStatsResponse, error)
	// TokenomicsStats queries overall tokenomics statistics
	TokenomicsStats(context.Context, *QueryTokenomicsStatsRequest) (*QueryTokenomicsStatsResponse, error)
}

